import java.util.*;

class Solution {
  public int countPairs(int[] nums) {
    Map<Integer, Integer> seen = new HashMap<>();
    int answer = 0;
    for (int x : nums) {
      // pad to 7 digits so swaps may move leading zeros (e.g. 10 <-> 1)
      char[] d = String.format("%07d", x).toCharArray();
      Set<Integer> reachable = new HashSet<>();
      reachable.add(x);
      for (int i = 0; i < 7; i++)
        for (int j = i + 1; j < 7; j++) {
          char t = d[i];
          d[i] = d[j];
          d[j] = t;
          reachable.add(Integer.parseInt(new String(d)));
          d[j] = d[i];
          d[i] = t;
        }
      for (int y : reachable) answer += seen.getOrDefault(y, 0);
      seen.merge(x, 1, Integer::sum);
    }
    return answer;
  }
}
